/**
 * Look up a manifest by tradition id. Falls back to the Aristotelian
 * manifest if the requested id is unknown (defensive — should not
 * happen in practice since TraditionId is the source-of-truth union).
 */
export function getManifest(id: TraditionId): string {
	return MANIFESTS[id] ?? MANIFESTS.aristotelian;
}
